# Check 1: canonical manifest allowed set - does the script define/enforce an allowed set from manifest?
Write-Output \"=== CHECK 1: Canonical manifest allowed set ===\"
if ("'$deploy -match '"'want_set') { Write-Output \"PASS: want_set enforced in source-verify phase\" } else { Write-Output \"FAIL: no want_set\" }
if ("'$deploy -match '"'want\\[') { Write-Output \"PASS: want[] dict enforced in post-install re-assert phase\" } else { Write-Output \"FAIL: no want[] in post-install\" }

# Check 2: manifest-driven copy (not blanket cp -a)
Write-Output \""'`n=== CHECK 2: Manifest-driven copy ==="
if ($deploy -match '"'manifest-driven install') { Write-Output \"PASS: manifest-driven install label present\" } else { Write-Output \"FAIL: no manifest-driven install\" }
if ("'$deploy -notmatch '"'cp -a \"\\"'$APP_V3_SRC"'"') { Write-Output \"PASS: no blanket cp -a of source tree\" } else { Write-Output \"FAIL: blanket cp -a found\" }

# Check 3: unlisted executable/importable/pyc rejected before deploy
Write-Output \""'`n=== CHECK 3: Unlisted/pyc rejection BEFORE deploy ==="
if ($deploy -match '"'\"EXTRA\"') { Write-Output \"PASS: EXTRA token present (unlisted files rejected)\" } else { Write-Output \"FAIL: no EXTRA check\" }
if ("'$deploy -match '"'PYC/CACHE') { Write-Output \"PASS: PYC/CACHE rejection present\" } else { Write-Output \"FAIL: no PYC/CACHE check\" }
if ("'$deploy -match '"'\\.pyc.*bad\\+\\+|\\.pyc.*bad\\+=|pyc.*bad') { Write-Output \"PASS: .pyc increments bad counter\" } else { Write-Output \"FAIL: .pyc bad-counter unclear\" }

# Check 4: post-install re-hash
Write-Output \""'`n=== CHECK 4: Post-install re-hash ==="
if ($deploy -match '"'HASH-MISMATCH-INSTALLED') { Write-Output \"PASS: HASH-MISMATCH-INSTALLED re-hash check present\" } else { Write-Output \"FAIL: no post-install rehash\" }
if ("'$deploy -match '"'EXTRA-INSTALLED') { Write-Output \"PASS: EXTRA-INSTALLED check present\" } else { Write-Output \"FAIL: no EXTRA-INSTALLED check\" }
if ("'$deploy -match '"'MISSING-INSTALLED') { Write-Output \"PASS: MISSING-INSTALLED check present\" } else { Write-Output \"FAIL: no MISSING-INSTALLED\" }"

